
package dev.starclient.client.gui;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

public class ClickGUI extends Screen {

    private static final int BACKGROUND = 0xF0101218;
        private static final int SIDEBAR = 0xFF171A22;
            private static final int PANEL = 0xFF20242E;
                private static final int CARD = 0xFF292E3A;
                    private static final int ACCENT = 0xFF8B72FF;
                        private static final int WHITE = 0xFFFFFFFF;
                            private static final int MUTED = 0xFF9A9EAA;

                                public ClickGUI() {
                                        super(Component.literal("Star Client"));
                                            }

                                                @Override
                                                    public void render(
                                                                GuiGraphics graphics,
                                                                            int mouseX,
                                                                                        int mouseY,
                                                                                                    float partialTick
                                                                                                        ) {
                                                                                                                super.render(graphics, mouseX, mouseY, partialTick);

                                                                                                                        int panelWidth = Math.min(620, this.width - 30);
                                                                                                                                int panelHeight = Math.min(360, this.height - 30);

                                                                                                                                        int x = (this.width - panelWidth) / 2;
                                                                                                                                                int y = (this.height - panelHeight) / 2;

                                                                                                                                                        int sidebarWidth = 65;
                                                                                                                                                                int contentX = x + sidebarWidth;

                                                                                                                                                                        // Main window
                                                                                                                                                                                graphics.fill(x, y, x + panelWidth, y + panelHeight, BACKGROUND);

                                                                                                                                                                                        // Sidebar
                                                                                                                                                                                                graphics.fill(x, y, contentX, y + panelHeight, SIDEBAR);

                                                                                                                                                                                                        // Logo
                                                                                                                                                                                                                graphics.drawString(
                                                                                                                                                                                                                                this.font, "S", x + 25, y + 20, ACCENT, false
                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                // Sidebar navigation
                                                                                                                                                                                                                                                        String[] navigation = {"UI", "HUD", "MOV", "VIS"};

                                                                                                                                                                                                                                                                for (int i = 0; i < navigation.length; i++) {
                                                                                                                                                                                                                                                                            int itemY = y + 65 + i * 42;

                                                                                                                                                                                                                                                                                        if (i == 0) {
                                                                                                                                                                                                                                                                                                        graphics.fill(
                                                                                                                                                                                                                                                                                                                                x + 8, itemY - 7,
                                                                                                                                                                                                                                                                                                                                                        x + sidebarWidth - 8, itemY + 17,
                                                                                                                                                                                                                                                                                                                                                                                0xFF343044
                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawCenteredString(
                                                                                                                                                                                                                                                                                                                                                                                                                                            this.font,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                navigation[i],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    x + sidebarWidth / 2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        itemY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            i == 0 ? ACCENT : MUTED
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Header
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                graphics.drawString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.font, "STAR CLIENT",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                contentX + 20, y + 17, WHITE, false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                graphics.drawString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.font, "Vision Bigger Than Eye",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                contentX + 20, y + 31, MUTED, false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Category tabs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int tabY = y + 58;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawPanel(graphics, contentX + 20, tabY, 85, 25);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawPanel(graphics, contentX + 113, tabY, 95, 25);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawPanel(graphics, contentX + 216, tabY, 80, 25);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawCenteredString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.font, "HUD", contentX + 62, tabY + 8, WHITE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawCenteredString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.font, "MOVEMENT", contentX + 160, tabY + 8, MUTED
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawCenteredString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.font, "VISUAL", contentX + 256, tabY + 8, MUTED
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Search bar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int searchX = contentX + 20;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int searchY = y + 96;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawPanel(graphics, searchX, searchY, panelWidth - 105, 25);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.font, "Search modules...",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        searchX + 10, searchY + 8, MUTED, false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Utility module cards
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int cardY = y + 137;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int cardWidth = (panelWidth - sidebarWidth - 60) / 3;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawModuleCard(graphics, contentX + 20, cardY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cardWidth, "Toggle Sprint");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawModuleCard(graphics, contentX + 30 + cardWidth, cardY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cardWidth, "Fullbright");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawModuleCard(graphics, contentX + 40 + cardWidth * 2, cardY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cardWidth, "Potion HUD");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawModuleCard(graphics, contentX + 20, cardY + 78,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cardWidth, "Armor HUD");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                drawModuleCard(graphics, contentX + 30 + cardWidth, cardY + 78,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cardWidth, "Motion Blur");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        drawModuleCard(graphics, contentX + 40 + cardWidth * 2, cardY + 78,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cardWidth, "More modules");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private void drawPanel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            GuiGraphics graphics,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int x, int y, int width, int height
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    graphics.fill(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    x, y, x + width, y + height, PANEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void drawModuleCard(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                GuiGraphics graphics,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int x, int y, int width, String name
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.fill(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        x, y, x + width, y + 65, CARD
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.drawString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.font, name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        x + 9, y + 10, WHITE, false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Settings button - bottom left
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                graphics.drawString(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.font, "⚙",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                x + 9, y + 43, MUTED, false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Toggle placeholder - bottom right
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        graphics.fill(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        x + width - 34, y + 42,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        x + width - 10, y + 54,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        0xFF454A58
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    